import React, { Component } from 'react'
import { connect } from 'react-redux';
import Alert from 'react-bootstrap/Alert'

class alerts extends Component {
    
    render() {
        
        console.log(this.props)
        
            const showErrorAlert = this.props.showErrorAlert ? {display: 'block'} : {display: 'none'};   
            const showSuccessAlert = this.props.showSuccessAlert ? {display: 'block'} : {display: 'none'};
            const showInfoAlert = this.props.showInfoAlert ? {display: 'block'} : {display: 'none'};
     
     
        return (
                
            <Alert className="error-alert alert-fixed" style={showErrorAlert} variant='danger' onClose={() => this.props.dismissErrorAlert()} dismissible>
                <Alert.Heading>Uh oh!</Alert.Heading>
                    {this.props.errorAlertText}
                <Alert.Link href="#" onClick={this.props.switchToSignup}>{this.props.errorAlertLinkText}</Alert.Link>
            </Alert>
              
   
              
    
          
        );
    }

}



function mapStateToProps(state) {
 
    return {
        showErrorAlert: state.showErrorAlert,
        showSuccessAlert: state.showSuccessAlert,
        showInfoAlert: state.showInfoAlert,
        errorAlertText: state.errorAlertText,
        errorAlertLinkText: state.errorAlertLinkText,
        successAlertText: state.successAlertText,
        infoAlertText: state.infoAlertText,
        showErrorAlert: state.showErrorAlert
    }
      
      
}

export default connect(mapStateToProps)(alerts);
